const MAGECITY_COLS = 8;

// Helper: place a multi-tile object from any tileset
// texArray = pre-sliced texture array, cols = tileset column count
function placeObject(container, texArray, cols, obj, worldX, worldY, tileSize) {
  tileSize = tileSize || 32;
  for (const [cx, cy] of obj.cells) {
    const tid = cx + cy * cols;
    if (!texArray[tid]) continue;
    const s = new PIXI.Sprite(texArray[tid]);
    s.x = worldX + (cx - obj.x) * tileSize;
    s.y = worldY + (cy - obj.y) * tileSize;
    container.addChild(s);
  }
}
